// Block (composition) — card payment fields assembled from form Components.
// Arranges only; composes Form/TextField/Grid/Button/Alert/Stack.
import type { FormEvent, Ref } from "react";
import { Form } from "../components/Form";
import { TextField } from "../components/TextField";
import { Grid } from "../layouts/Grid";
import { Button } from "../components/Button";
import { Alert } from "../components/Alert";
import { Stack } from "../layouts/Stack";
import "./PaymentForm.css";

export interface PaymentFormProps {
  /** Heading shown above the payment fields. */
  heading?: string;
  /** Called with the submitted card details. */
  onSubmit?: (data: Record<string, string>) => void;
  /** Form-level payment error, shown above the fields. */
  errorMessage?: string;
  /** Puts the pay button in a pending state and blocks re-submit. */
  isPending?: boolean;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function PaymentForm({
  heading,
  onSubmit,
  errorMessage,
  isPending,
  className,
  ref,
}: PaymentFormProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      cardholderName: String(data.get("cardholderName") ?? ""),
      cardNumber: String(data.get("cardNumber") ?? ""),
      expiry: String(data.get("expiry") ?? ""),
      cvc: String(data.get("cvc") ?? ""),
    });
  };

  return (
    <Form isPending={isPending}
      ref={ref}
      onSubmit={handleSubmit}
      className={className ? `sd-paymentform ${className}` : "sd-paymentform"}
    >
      <Stack gap="large" className="sd-paymentform__content">
        {heading && (
          <>
            <h1 className="sd-paymentform__heading sd-type-headline-medium">{heading}</h1>
          </>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Stack gap="medium" className="sd-paymentform__fields">
          <TextField
            label="Cardholder name"
            name="cardholderName"
            autoComplete="cc-name"
            isRequired
          />
          <TextField
            label="Card number"
            name="cardNumber"
            autoComplete="cc-number"
            inputMode="numeric"
            isRequired
          />
          <Grid columns={{ small: 1, medium: 2 }} gap="medium">
            <TextField
              label="Expiry"
              name="expiry"
              autoComplete="cc-exp"
              inputMode="numeric"
              placeholder="MM/YY"
              isRequired
            />
            <TextField
              label="CVC"
              name="cvc"
              autoComplete="cc-csc"
              inputMode="numeric"
              isRequired
            />
          </Grid>
        </Stack>
        <Button size="large" type="submit" variant="primary" isPending={isPending}>
          Pay
        </Button>
      </Stack>
    </Form>
  );
}

/* PaymentForm.css — arrangement only; Component look stays with its owners. */
.sd-paymentform {
  width: 100%;
}

.sd-paymentform__heading {
  margin: 0;
}
